-- 시험용 가상 여행(예시 상품)의 상세 내용. 다낭·치앙마이·파리는 일정까지, 나머지는 공통 안내만 채운다. 실제 여행은 관리자 화면에서 입력한다.
update public.trips set is_sample = true, min_participants = 4, host_name = '함께닿 호스트', meeting_i18n = '{"ko": "출발 7일 전 확정 안내와 함께 집합 장소와 시간을 알려 드려요.", "en": "We will send the meeting place and time with the confirmation notice 7 days before departure.", "zh": "出发前7天发送确认通知时，会告知集合地点和时间。", "ja": "出発の7日前の確定案内とともに、集合場所と時間をお知らせします。", "es": "Te enviaremos el lugar y la hora de encuentro con la confirmación, 7 días antes de la salida."}', includes_i18n = '{"ko": ["숙소 (2인 1실 기준)", "현지 이동 차량", "호스트 동행", "웰컴 모임과 대화 주제 카드"], "en": ["Accommodation (twin share)", "Local transfers", "Host accompanies the group", "Welcome gathering and conversation cards"], "zh": ["住宿（双人间）", "当地接送用车", "领队全程陪同", "欢迎聚会与话题卡片"], "ja": ["宿泊（2名1室）", "現地の送迎車", "ホストが同行", "ウェルカムの集まりと会話カード"], "es": ["Alojamiento (habitación doble)", "Traslados locales", "Anfitrión que acompaña", "Encuentro de bienvenida y tarjetas de conversación"]}', excludes_i18n = '{"ko": ["왕복 항공권", "식사 (자유 일정 시간)", "개인 경비와 여행자 보험"], "en": ["Round-trip flights", "Meals during free time", "Personal expenses and travel insurance"], "zh": ["往返机票", "自由活动时间的餐费", "个人开销与旅行保险"], "ja": ["往復航空券", "自由時間の食事", "個人の費用と旅行保険"], "es": ["Vuelos de ida y vuelta", "Comidas en tiempo libre", "Gastos personales y seguro de viaje"]}', host_bio_i18n = '{"ko": "여행을 함께 계획하고 첫날 웰컴 모임을 이끄는 호스트예요. 일정은 느슨하게, 어색함은 가볍게 풀어 드려요.", "en": "Your host plans the trip with you and leads the welcome gathering on day one. A relaxed schedule and an easy way to break the ice.", "zh": "领队与大家一起规划行程，并在第一天主持欢迎聚会。行程轻松，轻松打破尴尬。", "ja": "ホストは旅を一緒に計画し、初日のウェルカムの集まりを進行します。ゆるい日程で、気まずさを軽くほぐします。", "es": "Tu anfitrión planifica el viaje contigo y dirige el encuentro de bienvenida el primer día. Un plan relajado y un trato cercano para romper el hielo."}' where title like '[테스트]%';
update public.trips set itinerary_i18n = '{"ko": [{"title": "1일차 · 도착과 웰컴 모임", "desc": "공항에서 만나 숙소로 이동하고, 저녁에 가볍게 인사하는 웰컴 모임을 해요."}, {"title": "2일차 · 해변과 마사지", "desc": "오전엔 미케 비치에서 자유 시간, 오후엔 마사지, 저녁은 함께 해산물 식당으로 가요."}, {"title": "3일차 · 바나산 또는 자유 일정", "desc": "원하는 사람은 바나산으로, 나머지는 카페와 쇼핑 등 자유롭게 다녀요."}, {"title": "4~5일차 · 마지막 저녁과 귀국", "desc": "마지막 저녁을 함께하고 공항으로 이동해요."}], "en": [{"title": "Day 1 · Arrival and welcome gathering", "desc": "Meet at the airport, transfer to the hotel, and say hello at a relaxed welcome dinner."}, {"title": "Day 2 · Beach and massage", "desc": "Free time at My Khe Beach in the morning, a massage in the afternoon, then seafood together."}, {"title": "Day 3 · Ba Na Hills or free time", "desc": "Join the Ba Na Hills trip, or spend the day on cafés and shopping as you like."}, {"title": "Days 4-5 · Farewell dinner and flight home", "desc": "Share a last dinner together, then head to the airport."}], "zh": [{"title": "第1天 · 抵达与欢迎聚会", "desc": "在机场会合后前往酒店，晚上举行轻松的欢迎聚餐。"}, {"title": "第2天 · 海滩与按摩", "desc": "上午在美溪海滩自由活动，下午按摩，晚上一起吃海鲜。"}, {"title": "第3天 · 巴拿山或自由活动", "desc": "想去的人前往巴拿山，其他人可自由逛咖啡馆和购物。"}, {"title": "第4~5天 · 告别晚餐与返程", "desc": "一起吃最后一顿晚餐，然后前往机场。"}], "ja": [{"title": "1日目 · 到着とウェルカムの集まり", "desc": "空港で合流して宿へ移動し、夜は気軽なウェルカムディナーで挨拶します。"}, {"title": "2日目 · ビーチとマッサージ", "desc": "午前はミーケビーチで自由時間、午後はマッサージ、夜は一緒にシーフードへ。"}, {"title": "3日目 · バナヒルズまたは自由行動", "desc": "希望者はバナヒルズへ、それ以外はカフェやショッピングを自由に楽しみます。"}, {"title": "4~5日目 · 最後の夕食と帰国", "desc": "最後の夕食を一緒にとって、空港へ移動します。"}], "es": [{"title": "Día 1 · Llegada y encuentro de bienvenida", "desc": "Nos vemos en el aeropuerto, vamos al hotel y nos saludamos en una cena de bienvenida relajada."}, {"title": "Día 2 · Playa y masaje", "desc": "Mañana libre en la playa de My Khe, masaje por la tarde y marisco juntos por la noche."}, {"title": "Día 3 · Ba Na Hills o tiempo libre", "desc": "Quien quiera va a Ba Na Hills; el resto disfruta de cafés y compras a su aire."}, {"title": "Días 4-5 · Cena de despedida y regreso", "desc": "Compartimos una última cena y vamos al aeropuerto."}]}' where id = '7edd9d6f-8589-42d5-866e-912caaaa6abf';
update public.trips set itinerary_i18n = '{"ko": [{"title": "1일차 · 도착과 구시가지 산책", "desc": "체크인 후 구시가지를 걸으며 저녁 시장에서 첫 식사를 해요."}, {"title": "2일차 · 카페 투어", "desc": "님만해민 골목의 카페를 함께 돌며 각자 취향의 한 곳을 골라 봐요."}, {"title": "3~4일차 · 가벼운 트레킹", "desc": "초보도 걷기 쉬운 코스로 숲길과 폭포를 걸어요. 오후엔 휴식 시간이 있어요."}, {"title": "5~6일차 · 자유 일정과 마무리", "desc": "마사지나 쇼핑을 즐기고 마지막 저녁을 함께한 뒤 귀국해요."}], "en": [{"title": "Day 1 · Arrival and Old City stroll", "desc": "Check in, then walk the Old City and have a first meal at the night market."}, {"title": "Day 2 · Café hopping", "desc": "Visit cafés in the Nimman area together and pick your favorite."}, {"title": "Days 3-4 · Easy trekking", "desc": "Walk forest trails and waterfalls on easy routes. There is rest time in the afternoon."}, {"title": "Days 5-6 · Free time and wrap-up", "desc": "Enjoy a massage or shopping, share a last dinner, then fly home."}], "zh": [{"title": "第1天 · 抵达与古城漫步", "desc": "办理入住后漫步古城，在夜市享用第一餐。"}, {"title": "第2天 · 咖啡馆巡游", "desc": "一起逛宁曼路的咖啡馆，选出各自最喜欢的一家。"}, {"title": "第3~4天 · 轻松徒步", "desc": "走初学者也容易的路线，穿过森林小径和瀑布。下午有休息时间。"}, {"title": "第5~6天 · 自由活动与结束", "desc": "享受按摩或购物，一起吃最后一顿晚餐后返程。"}], "ja": [{"title": "1日目 · 到着と旧市街散策", "desc": "チェックイン後、旧市街を歩き、ナイトマーケットで最初の食事をします。"}, {"title": "2日目 · カフェ巡り", "desc": "ニマンヘミンのカフェを一緒に巡り、それぞれのお気に入りを選びます。"}, {"title": "3~4日目 · 軽いトレッキング", "desc": "初心者でも歩きやすいコースで森の道と滝を歩きます。午後は休憩の時間があります。"}, {"title": "5~6日目 · 自由行動と締めくくり", "desc": "マッサージやショッピングを楽しみ、最後の夕食を一緒にして帰国します。"}], "es": [{"title": "Día 1 · Llegada y paseo por la ciudad vieja", "desc": "Check-in, paseo por la ciudad vieja y primera cena en el mercado nocturno."}, {"title": "Día 2 · Ruta de cafés", "desc": "Recorremos cafés de la zona de Nimman y cada uno elige su favorito."}, {"title": "Días 3-4 · Senderismo suave", "desc": "Caminamos por senderos y cascadas en rutas fáciles. Por la tarde hay tiempo de descanso."}, {"title": "Días 5-6 · Tiempo libre y despedida", "desc": "Masaje o compras, una última cena juntos y regreso a casa."}]}' where id = 'd7b9a750-5398-4860-8fc5-7e6f23eb2257';
update public.trips set itinerary_i18n = '{"ko": [{"title": "1일차 · 도착과 센강 산책", "desc": "숙소에 짐을 풀고 해 질 무렵 센강변을 걸으며 인사해요."}, {"title": "2~3일차 · 미술관 데이", "desc": "오르세·루브르 등 관심 있는 미술관을 골라 관람하고, 사이사이 카페에서 쉬어요."}, {"title": "4일차 · 몽마르트르와 자유 일정", "desc": "언덕 동네를 함께 걷고, 오후엔 각자 하고 싶은 일을 해요."}, {"title": "5~6일차 · 마지막 저녁과 귀국", "desc": "마지막 저녁을 함께하고 공항으로 이동해요."}], "en": [{"title": "Day 1 · Arrival and a stroll along the Seine", "desc": "Drop your bags and say hello on a sunset walk along the Seine."}, {"title": "Days 2-3 · Museum days", "desc": "Choose the museums you like, such as Orsay or the Louvre, with café breaks in between."}, {"title": "Day 4 · Montmartre and free time", "desc": "Walk the hilltop neighborhood together, then spend the afternoon as you wish."}, {"title": "Days 5-6 · Farewell dinner and flight home", "desc": "Share a last dinner together, then head to the airport."}], "zh": [{"title": "第1天 · 抵达与塞纳河漫步", "desc": "放好行李后，在日落时分沿塞纳河散步、互相认识。"}, {"title": "第2~3天 · 美术馆日", "desc": "选择奥赛、卢浮宫等感兴趣的美术馆参观，期间在咖啡馆休息。"}, {"title": "第4天 · 蒙马特与自由活动", "desc": "一起漫步山丘街区，下午自由安排。"}, {"title": "第5~6天 · 告别晚餐与返程", "desc": "一起吃最后一顿晚餐，然后前往机场。"}], "ja": [{"title": "1日目 · 到着とセーヌ川の散歩", "desc": "荷物を置いて、夕暮れのセーヌ川沿いを歩きながら挨拶します。"}, {"title": "2~3日目 · 美術館の日", "desc": "オルセーやルーヴルなど気になる美術館を選んで鑑賞し、合間にカフェで休みます。"}, {"title": "4日目 · モンマルトルと自由行動", "desc": "丘の街を一緒に歩き、午後はそれぞれ好きに過ごします。"}, {"title": "5~6日目 · 最後の夕食と帰国", "desc": "最後の夕食を一緒にとって、空港へ移動します。"}], "es": [{"title": "Día 1 · Llegada y paseo por el Sena", "desc": "Dejamos las maletas y nos saludamos en un paseo al atardecer junto al Sena."}, {"title": "Días 2-3 · Días de museos", "desc": "Elegimos museos como Orsay o el Louvre, con pausas en cafés."}, {"title": "Día 4 · Montmartre y tiempo libre", "desc": "Paseamos por el barrio de la colina y por la tarde cada uno hace lo que quiere."}, {"title": "Días 5-6 · Cena de despedida y regreso", "desc": "Compartimos una última cena y vamos al aeropuerto."}]}' where id = '65c25411-1d0e-4361-a902-a95877747e80';
